#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { parse } from '../src/parse.js';

process.stdout.write(`${JSON.stringify(parse(readFileSync(0, 'utf8')))}\n`);
/** Rows of a delimited table as objects keyed by the header row. */
export function parse(text, sep = ',') {
  const [head, ...rows] = text.trim().split(/\r?\n/).map((l) => l.split(sep));
  return rows.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i] ?? ''])));
}
csv.test.js
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { parse } from '../src/parse.js';

test('parse', () => assert.deepEqual(parse('a,b\n1,2\n'), [{ a: '1', b: '2' }]));
test('cli', () => assert.equal(execFileSync('node', ['bin/csv2json.js'], { input: 'a,b\n1,2\n', encoding: 'utf8' }), '[{"a":"1","b":"2"}]\n'));
# csv2json

```
node bin/csv2json.js < table.csv
```

Prints the rows as a JSON array of objects keyed by the header row.

Tests: `npm test`.
